areas=[]
for m,n,ring,anchors,urls,note in rows:
 if ring[-1]!=ring[0]:ring.append(ring[0])
 paths=['data/neighborhoods/expansion-20261115-round4/contexts/'+K[m]+'/'+x+'.geojson.gz' for x in ['roads','areas']]
 if n=='Felsőtag':paths.append('data/neighborhoods/expansion-20261115-round4/contexts/'+K[m]+'/municipality.geojson')
 areas.append(dict(municipality=m,name=n,ring=ring,anchors=anchors,urls=urls,note=note,contextPaths=paths))
(H/'specs/final-localities.json').write_text(json.dumps({'areas':areas},ensure_ascii=False,indent=2)+'\n')
